# zcube @VERSION@ for macOS: the lines that add it to the `zigbox` formula of Zigbox/homebrew-tap,
# so that `brew install Zigbox/tap/zigbox` installs zbx and zcube together (docs/macos.md).
#
# Generated by `zig build mac-release` in Zigbox/zigcube from packaging/homebrew/zcube-resource.rb,
# which holds placeholders for the version, the archive's URL and its SHA-256. The archive is the
# universal (arm64 and x86_64) zcube, signed with Developer ID and notarized, from Zigcube's GitHub
# release. Paste each part where its comment says, in the formula Zigbox's own mac-release wrote.

# 1. In the class body, after `depends_on :macos`:
  resource "zcube" do
    url "@URL@"
    sha256 "@SHA256@"
  end

# 2. In `def install`, after `bin.install "zbx"`:
    resource("zcube").stage { bin.install "zcube" }

# 3. In `test do`; neither command reaches a server (zcube has no --version flag):
    assert_match "the Zigcube command line", shell_output("#{bin}/zcube help")
    assert_match "only on Linux", shell_output("#{bin}/zcube explain E0122")
